package desktop

import "fyne.io/fyne/v2"

// App represents a desktop application with additional desktop-specific capabilities.
// This extends the base fyne.App interface with methods for managing application title.
//
// Since: 2.5
type App interface {
	fyne.App

	// Title returns the application title.
	// The title is typically shown in the application switcher, dock, or task bar.
	Title() string

	// SetTitle sets the application title.
	// The title is typically shown in the application switcher, dock, or task bar.
	SetTitle(title string)
}

